import importlib.util
import json
import os
import sys

RUN = sys.argv[1] if len(sys.argv) > 1 else '/workspace/runs/83ed278ac33df92c592b4c5f3d6a1ca0170aab56'


class Memory:
    """Stands in for the frozen memory path the module reads."""

    def __init__(self, path):
        self.path = path

    def read_text(self, *args, **kwargs):
        with open(self.path, encoding='utf-8') as handle:
            return handle.read()


def load(task):
    spec = importlib.util.spec_from_file_location(
        'retrieval_%s' % task, '/workspace/harness/solver/tools/retrieval.py'
    )
    module = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(module)
    module.Path = lambda _: Memory(f'{RUN}/{task}/memory.json')
    return module


def message_text(entry):
    content = entry.get('content')
    if isinstance(content, list):
        content = ''.join(
            block if isinstance(block, str) else block.get('text', '')
            for block in content
        )
    return content or ''


def conversation(task, ei, si):
    with open(f'{RUN}/{task}/conversations/{ei:04d}/sample-{si}.json') as handle:
        return json.load(handle)


def case_count(text):
    return len([part for part in text.split('\n\n') if part.startswith('Q: ')])


def evidence_input(doc):
    user = message_text([m for m in doc['messages'] if m.get('role') == 'user'][0])
    return user.split('\n\n1. Call `retrieve_examples`')[0]


def main():
    for task in ('USPTO', 'Symptom2Disease', 'LawBench'):
        module = load(task)
        same = 0
        total = 0
        for index in range(100):
            for sample in (0, 1):
                path = f'{RUN}/{task}/conversations/{index:04d}/sample-{sample}.json'
                if not os.path.exists(path):
                    continue
                doc = conversation(task, index, sample)
                tools = [m for m in doc['messages'] if m.get('role') == 'tool']
                if not tools:
                    continue
                recorded = message_text(tools[0])
                if not recorded.startswith('Q: '):
                    continue
                total += 1
                same += module.select_examples(evidence_input(doc)) == recorded
        print(f'{task}: shipped evidence byte-identical {same}/{total}')
        # the search, asked the problem's own question, must be the same tier
        for index in range(100):
            path = f'{RUN}/{task}/conversations/{index:04d}/sample-0.json'
            if not os.path.exists(path):
                continue
            doc = conversation(task, index, 0)
            tools = [m for m in doc['messages'] if m.get('role') == 'tool']
            if not tools:
                continue
            text = module.search(evidence_input(doc), budget=module.MAX_CHARS)
            recorded = message_text(tools[0])
            header, _, body = text.partition('\n\n')
            print(
                f'   search(question, full budget) vs shipped cases: '
                f'{body == recorded}  header: {header}'
            )
            break


if __name__ == '__main__':
    main()

